cards.solution:
tugas = []

while True:
    perintah = input().strip()
    if perintah == "keluar":
        break
    if perintah.startswith("tambah "):
        tugas.append(perintah[7:])
    elif perintah == "lihat":
        if not tugas:
            print("Belum ada tugas")
        for no, judul in enumerate(tugas, start=1):
            print(f"{no}. {judul}")
